-- 빌더로 조립한다

private List<Member> searchByBuilder(String username, Integer minAge,
                                     Integer maxAge, String teamName) {
    BooleanBuilder builder = new BooleanBuilder();

    if (username != null)  builder.and(member.username.startsWith(username));
    if (minAge != null)    builder.and(member.age.goe(minAge));
    if (maxAge != null)    builder.and(member.age.loe(maxAge));
    if (teamName != null)  builder.and(member.team.name.eq(teamName));

    return queryFactory.selectFrom(member).where(builder).fetch();
}

