-- 아무 조건 없으면 막는다

private List<Member> searchSafe(String username, Integer minAge) {
    BooleanBuilder builder = new BooleanBuilder();
    if (username != null) builder.and(member.username.startsWith(username));
    if (minAge != null)   builder.and(member.age.goe(minAge));

    if (!builder.hasValue()) {
        throw new IllegalArgumentException("조건이 하나는 있어야 한다");
    }
    return queryFactory.selectFrom(member).where(builder).fetch();
}

@Test
void 막기() {
    try {
        searchSafe(null, null);
    } catch (Exception e) {
        System.out.println(e.getClass().getSimpleName() + ": "
                + e.getMessage());
    }
}

