// 이렇게 하면 부수효과가 생긴다
private void addUsername(BooleanBuilder builder, String username) {
    if (username != null) builder.and(member.username.startsWith(username));
}

@Test
void 부수효과() {
    BooleanBuilder builder = new BooleanBuilder();
    addUsername(builder, "m");
    System.out.println("밖에서 본 값: " + builder.getValue());
}

밖에서 본 값: member1.username like m% escape '!'

