-- 조합해 쓰기도 어렵다

@Test
void 조합() {
    BooleanBuilder a = new BooleanBuilder(member.age.goe(20));
    BooleanBuilder b = new BooleanBuilder(member.team.isNotNull());

    BooleanBuilder merged = new BooleanBuilder();
    merged.and(a).and(b);

    em.clear();
    System.out.println("건수: " + queryFactory.selectFrom(member)
            .where(merged).fetch().size());
    System.out.println("a 는 그대로? " + a.getValue());
}

